ls -a && ls node_modules >/dev/null 2>&1 && echo HAS_NODE_MODULES; (command -v psql pg_isready docker; pg_isready -h localhost -p 5433) 2>&1; python3 -c "
import json
c=json.load(open('postman/shop-api.postman_collection.json'))
def walk(items,d=0):
  for i in items:
    if 'item' in i: print('  '*d+'[F] '+i['name']); walk(i['item'],d+1)
    else: print('  '*d+i['name']+' :: '+json.dumps(i['request'])[:300])
walk(c['item'])
print(c.get('variable'))
"

